const topic = $json.topic;
const category = $json.category;
if (!topic) throw new Error('Research requires topic.');
if (!category) throw new Error('Research requires category.');

return [{
  json: {
    topic,
    category,
    childContext: $json.childContext || {},
    familyContext: $json.familyContext || {},
    queries: [
      `${topic} recommandations officielles enfant`,
      `${topic} source fiable pediatrie`,
      `${topic} universite recherche enfant`
    ]
  }
}];

const validation = $json;
const acceptedSources = (validation.sources || []).filter(source => source.accepted);
const topic = $('Prepare Research Request').first().json.topic;
const category = $('Prepare Research Request').first().json.category;

return [{
  json: {
    topic,
    category,
    whyNow: '',
    executiveSummary: '',
    keyPoints: [],
    sources: acceptedSources.map(source => ({
      title: source.title,
      url: source.url,
      publisher: source.publisher,
      date: source.publicationDate,
      readingTimeMinutes: source.readingTimeMinutes || 0,
      sourceType: source.sourceType,
      score: source.score
    })),
    discussionQuestions: [],
    practicalIdeas: [],
    warnings: acceptedSources.length === 0 ? ['Je ne peux pas confirmer cette information à partir de sources suffisamment fiables.'] : []
  }
}];
